-- ====================================================
-- Cloudflare D1 Schema & Initial Seed for DineVault
-- Compatible with SQLite / Cloudflare D1 Console
-- ====================================================

DROP TABLE IF EXISTS site_pages;
CREATE TABLE site_pages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    page_name TEXT NOT NULL UNIQUE,
    content_json TEXT NOT NULL
);

DROP TABLE IF EXISTS restaurants;
CREATE TABLE restaurants (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    status TEXT NOT NULL DEFAULT 'pending',
    restaurant_json TEXT NOT NULL
);

DROP TABLE IF EXISTS contact_submissions;
CREATE TABLE contact_submissions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT NOT NULL,
    phone TEXT DEFAULT '',
    subject TEXT NOT NULL,
    message TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'unread',
    submitted_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

DROP TABLE IF EXISTS admin_settings;
CREATE TABLE admin_settings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL
);

-- Default Admin (admin@cateringmenu.com / CateringAdmin@1324$)
INSERT INTO admin_settings (username, password_hash) VALUES ('admin@cateringmenu.com', 'CateringAdmin@1324$');

