INSERT INTO site_pages (page_name, content_json) VALUES ('global', '{"nav":{"logo_image":"/assets/img/catering-menu-logo.png","logo_icon":"fas fa-utensils","logo_text":"Catering Menu","links":[{"label":"Home","url":"/"},{"label":"Caterers","url":"/listings"},{"label":"About Us","url":"/about"},{"label":"FAQs","url":"/faqs"},{"label":"Contact","url":"/contact"}],"cta_btn":{"label":"List Your Business","url":"/get-listed"}},"footer":{"about_heading":"About Catering Menu","about_text":"Catering Menu is the premier discovery directory connecting event planners and hosts with top-rated caterers, verified menus, genuine reviews, and seamless booking inquiries for unforgettable celebrations.","quick_heading":"Quick Links","quick_links":[{"label":"Home","url":"/"},{"label":"Caterers","url":"/listings"},{"label":"About Us","url":"/about"},{"label":"List Your Business","url":"/get-listed"},{"label":"FAQs","url":"/faqs"},{"label":"Contact","url":"/contact"}],"cuisines_heading":"Popular Catering","cuisine_links":[{"label":"Wedding Catering","url":"/listings/wedding"},{"label":"Corporate Galas","url":"/listings/corporate"},{"label":"Live BBQ & Grill Stations","url":"/listings/bbq"},{"label":"Italian & Wood-Fired","url":"/listings/italian"},{"label":"Royal Indian & Asian","url":"/listings/asian"},{"label":"Cocktails & Canapés","url":"/listings/cocktail"}],"legal_heading":"Legal & Policy","legal_links":[{"label":"Privacy Policy","url":"/privacy"},{"label":"Terms of Service","url":"/terms"},{"label":"Disclaimer","url":"/disclaimer"}],"show_socials":false,"socials":[],"copyright":"\u00a9 2026 Catering Menu. All rights reserved."},"seo_global":{"indexing_enabled":false,"default_og_image":"https://www.catering-menu.com/assets/img/catering-menu-logo.png","site_name":"Catering Menu"}}');

INSERT INTO site_pages (page_name, content_json) VALUES ('home', '{"seo":{"title":"Catering Menu - Premier Catering Directory & Event Menus","description":"Discover top-rated catering services, browse curated event food menus, verified client reviews, and book premier caterers for weddings, corporate galas, and private celebrations.","og_image":"https://www.catering-menu.com/assets/img/catering-menu-logo.png"},"hero":{"badge":"Premier Catering Directory","title":"Discover Extraordinary Catering Experiences","subtitle":"Explore handpicked caterers, browse exquisite event menus, and find the perfect culinary service for your wedding, corporate event, or private party.","search_placeholder":"Search caterers by name, cuisine, or occasion...","search_btn":{"label":"Explore Now","url":"#restaurants"},"stats":[{"number":"2,500+","label":"Caterers Listed"},{"number":"15,000+","label":"Curated Menus"},{"number":"50,000+","label":"Happy Guests Served"}]},"how_it_works":{"overline":"Simple Process","title":"How Catering Menu Works","subtitle":"Booking the ideal catering for your event is effortless in three simple steps.","steps":[{"icon":"fas fa-search","title":"Browse & Discover","text":"Explore top-rated caterers. Filter by cuisine, event type, or guest capacity to find your ideal match."},{"icon":"fas fa-book-open","title":"Explore Menus & Reviews","text":"Browse detailed food menus, buffet items, and verified reviews from past event hosts."},{"icon":"fas fa-phone-volume","title":"Connect & Plan","text":"Get in touch directly with the caterer, customize your menu, and create unforgettable moments."}]},"featured":{"overline":"Top Rated","title":"Featured Catering Services","subtitle":"Handpicked catering partners for weddings, corporate galas, and special celebrations.","view_all_btn":{"label":"View All Caterers","url":"/listings"}},"split_1":{"overline":"Why Choose Us","title":"Curated Catering Teams for Every Occasion","text":"Every catering service on Catering Menu is handpicked by our culinary experts. We visit, taste, and verify kitchen standards and event execution before feature approval. Our rigorous selection process ensures your guests enjoy nothing short of culinary perfection.","bullets":[{"icon":"fas fa-check-circle","text":"Handpicked & verified catering partners"},{"icon":"fas fa-check-circle","text":"Customizable multi-course event menus"},{"icon":"fas fa-check-circle","text":"Live food counters & buffet setups"},{"icon":"fas fa-check-circle","text":"Authentic verified host reviews & photos"}],"image_url":"https://images.unsplash.com/photo-1555244162-803834f70033?w=800","image_alt":"Luxury catering buffet setup","btn":{"label":"Learn More","url":"/about"}},"split_2":{"overline":"Community Driven","title":"Real Reviews from Real Event Hosts","text":"From weddings to corporate conferences, over 50,000 event hosts share authentic experiences, setup photos, and honest reviews. Make confident choices backed by genuine guest satisfaction scores.","bullets":[{"icon":"fas fa-shield-alt","text":"100% verified host reviews"},{"icon":"fas fa-users","text":"50,000+ active event planners"},{"icon":"fas fa-camera","text":"Photos of real buffets & live counters"},{"icon":"fas fa-trophy","text":"Top caterer excellence recognition"}],"image_url":"https://images.unsplash.com/photo-1511795409834-ef04bbd61622?w=800","image_alt":"Guests enjoying catering at celebration","btn":{"label":"Browse Reviews","url":"/listings"}},"cta":{"title":"Own a Catering Business?","text":"Join Catering Menu and connect with thousands of event organizers, wedding planners, and corporate hosts looking for exceptional food services.","btn":{"label":"List Your Business Today","url":"/get-listed"}}}');

INSERT INTO site_pages (page_name, content_json) VALUES ('about', '{"seo":{"title":"About Us - Catering Menu","description":"Learn about Catering Menu, our mission to connect event hosts with premier catering services, verified event food menus, and transparent client reviews.","og_image":"https://www.catering-menu.com/assets/img/catering-menu-logo.png"},"hero":{"title":"About Catering Menu","subtitle":"Connecting event hosts, wedding planners, and families with unforgettable catering experiences and verified food menus."},"story":{"overline":"Our Story","title":"Born from a Passion for Unforgettable Celebrations","paragraphs":["Planning an event is a labor of love, but finding reliable catering with clear pricing, genuine food photos, and authentic reviews used to be frustratingly opaque. In 2024, Catering Menu was founded with a singular purpose: to bring complete transparency, culinary artistry, and peace of mind to event hosts everywhere.","Today, Catering Menu connects thousands of brides, event directors, family party hosts, and corporate organizers with handpicked, verified catering specialists. Whether you need a 5-course plated banquet for 500 guests or an artisanal food truck for an intimate backyard gathering, we make culinary discovery effortless and inspired."],"badge_card":{"title":"Built for Caterers & Event Hosts","text":"Every catering profile features verified menus, direct high-resolution food presentation photos, transparent pricing tiers, and direct contact options \u2014 zero middleman commissions.","icon":"fas fa-award"}},"pillars":{"overline":"Core Values","title":"What Drives Catering Menu","subtitle":"Our guiding principles ensure excellence at every banquet table and private celebration.","items":[{"icon":"fas fa-award","title":"Curated Culinary Excellence","text":"We do not accept just anyone. Every caterer undergoes inspection for culinary standards, food safety hygiene, and verified event execution."},{"icon":"fas fa-book-open","title":"Complete Menu Transparency","text":"Browse multi-course menus, dietary accommodations (halal, kosher, vegan, gluten-free), live counter options, and price ranges upfront."},{"icon":"fas fa-shield-alt","title":"Authentic Host Feedback","text":"Every review is vetted to reflect real client experiences, helping you select a culinary partner you can trust implicitly."},{"icon":"fas fa-handshake","title":"Bespoke Event Connections","text":"Directly communicate with caterers, schedule tastings, customize dishes, and secure your event dates with complete confidence."}]},"difference":{"overline":"The Difference","title":"Why Hosts & Caterers Choose Us","rows":[{"feature":"Verified Menus & Direct Pricing","catering_menu":"Transparent multi-course menus with dish photos","traditional":"Hidden pricing, generic contact forms only"},{"feature":"Dedicated Branded Subdomain","catering_menu":"Every caterer gets a custom subdomain link","traditional":"Buried inside generic listing portals"},{"feature":"Live Map & Service Areas","catering_menu":"GPS mapping with specific multi-branch radii","traditional":"Vague city-wide descriptions"},{"feature":"Direct Host Inquiries","catering_menu":"Direct client connection with 0% commissions","traditional":"High intermediary booking fees"}]},"stats":[{"number":"2,500+","label":"Caterers Listed"},{"number":"15,000+","label":"Curated Menus"},{"number":"50,000+","label":"Happy Event Guests"},{"number":"120+","label":"Cities Covered"}],"cta":{"title":"Own a Catering Business?","text":"Join Catering Menu today to showcase your culinary artistry, receive your own branded subdomain, and connect with high-intent event organizers.","btn":{"label":"List Your Catering Business","url":"/get-listed"}}}');

INSERT INTO site_pages (page_name, content_json) VALUES ('contact', '{"seo":{"title":"Contact Us - Catering Menu","description":"Get in touch with the Catering Menu support team for inquiries, caterer partnerships, booking support, or feedback.","og_image":"https://www.catering-menu.com/assets/img/catering-menu-logo.png"},"hero":{"title":"Get In Touch","subtitle":"Have a question, suggestion, or partnership inquiry? We would love to hear from you."},"form":{"name_placeholder":"Your Full Name","email_placeholder":"Your Email Address","subject_placeholder":"Subject","message_placeholder":"Your Message","submit_btn":{"label":"Send Message","url":"#"},"success_msg":"Thank you! Your message has been received."},"info":{"title":"Contact Information","items":[{"icon":"fas fa-map-marker-alt","label":"Address","value":"123 Gourmet Avenue, Culinary District, NY 10001"},{"icon":"fas fa-phone-alt","label":"Phone","value":"+1 (555) 987-6543"},{"icon":"fas fa-envelope","label":"Email","value":"hello@catering-menu.com"},{"icon":"fas fa-clock","label":"Hours","value":"Mon \u2013 Fri: 9:00 AM \u2013 6:00 PM"}]}}');

INSERT INTO site_pages (page_name, content_json) VALUES ('faqs', '{"seo":{"title":"Frequently Asked Questions - Catering Menu","description":"Find answers to common questions about booking caterers, listing your catering service, verified reviews, custom food menus, and pricing on Catering Menu.","og_image":"https://www.catering-menu.com/assets/img/catering-menu-logo.png"},"hero":{"title":"Frequently Asked Questions","subtitle":"Everything you need to know about finding caterers, booking events, and listing your business on Catering Menu."},"categories":[{"id":"all","label":"All Questions"},{"id":"hosts","label":"Event Hosts & Planning"},{"id":"menus","label":"Menu & Dietary Requirements"},{"id":"caterers","label":"Caterer Listings & Subdomains"}],"faq_items":[{"category":"hosts","question":"How do I find and choose the right caterer for my event?","answer":"Browse our Listings Directory to explore approved caterers. Filter by cuisine (Indian, Italian, BBQ, French, etc.), guest capacity, and rating. Each caterer profile features their full multi-course menu, banquet setup photos, verified reviews, and service locations."},{"category":"hosts","question":"How far in advance should I book my event catering?","answer":"For major events like weddings and corporate annual galas, we recommend booking 4 to 9 months in advance, especially during peak holiday and spring wedding seasons. For smaller celebrations or private dinners, 2 to 4 weeks is typically sufficient."},{"category":"hosts","question":"Can I request a private food tasting before finalizing my booking?","answer":"Yes! Most premier caterers listed on Catering Menu offer menu tastings for weddings and large gatherings. You can coordinate tasting sessions directly with the caterer through their profile contact information."},{"category":"hosts","question":"How do client reviews work on Catering Menu?","answer":"Event hosts who have booked or experienced a catering service can leave verified reviews, star ratings, and feedback on the caterer dedicated profile. Our moderation team screens submissions to ensure authentic, trustworthy feedback."},{"category":"menus","question":"Do caterers accommodate special dietary requirements and food allergies?","answer":"Yes. Our catering partners cater to a wide range of dietary needs, including Vegetarian, Vegan, Gluten-Free, Halal, Kosher, Nut-Free, and Dairy-Free. Look for dietary badges on each profile or contact the caterer directly to request custom menu accommodations."},{"category":"menus","question":"What is the difference between Plated, Buffet, and Live Counter service styles?","answer":"Plated service is a formal multi-course meal served directly to seated guests. Buffet service features elegant chafing stations where guests serve themselves from curated options. Live Counters (such as Live Tandoor, Sushi Bars, or Pasta Wheels) feature on-site chefs cooking fresh dishes right before your guests."},{"category":"menus","question":"Can I customize the menu items or request off-menu culinary dishes?","answer":"Absolutely. Catering menus on our platform serve as chef-curated foundations. Most caterers are delighted to tailor appetizer selections, fusion courses, signatures cocktails, and midnight dessert stations to match your event theme."},{"category":"menus","question":"Are beverages, bartending services, and tableware included with catering packages?","answer":"This depends on the caterer. Many full-service caterers offer complete packages with bartenders, signature mocktails, chinaware, linen, and glassware, while others focus exclusively on food preparation. Check the caterer info tab or reach out directly for package specifics."},{"category":"caterers","question":"How do I list my catering business on Catering Menu?","answer":"Navigate to the List Your Business page and fill out the submission form with your business name, specialty cuisines, banner photo, visual menu cards, and locations. Our curation team will review and approve your profile within 24 to 48 hours."},{"category":"caterers","question":"Is it free to list my catering business?","answer":"Yes, listing your catering service on Catering Menu is completely free. We make quality catering discovery accessible for event hosts everywhere without charging exorbitant broker commissions."},{"category":"caterers","question":"What is a dedicated caterer subdomain and how do I use it?","answer":"Every approved caterer receives their own custom subdomain URL (for example, https://spice-route.catering-menu.com). You can use this branded link on your business cards, Instagram bio, marketing brochures, and email signatures to showcase your verified menus and client reviews!"},{"category":"caterers","question":"How do I update my catering menu, seasonal packages, or pricing?","answer":"You can update your menu at any time by accessing your admin panel or contacting our support team. We also support direct PDF menu downloads for caterers who prefer uploading graphic banquet brochures."}],"cta":{"title":"Own a Catering Business?","text":"Join Catering Menu today to showcase your culinary creations, get your own branded subdomain, and receive inquiries from thousands of event organizers.","btn":{"label":"List Your Catering Business","url":"/get-listed"}}}');

INSERT INTO site_pages (page_name, content_json) VALUES ('get-listed', '{"seo":{"title":"List Your Catering Business - Catering Menu","description":"List your catering business on Catering Menu for free. Showcase your event menus, food photos, service areas, and connect with thousands of event planners.","og_image":"https://www.catering-menu.com/assets/img/catering-menu-logo.png"},"hero":{"title":"List Your Catering Business","subtitle":"Join thousands of caterers already on Catering Menu. Showcase your event menus, gather host reviews, and attract bookings."},"benefits":[{"icon":"fas fa-bolt","title":"Free Lifetime Listing","text":"Get discovered by corporate planners, wedding organizers, and private event hosts with zero listing fees or hidden commissions."},{"icon":"fas fa-globe","title":"Dedicated Branded Subdomain","text":"Receive your unique URL (e.g. your-name.catering-menu.com) to share on social media, business cards, and marketing brochures."},{"icon":"fas fa-camera-retro","title":"Direct Menu & Gallery Cards","text":"Showcase visual menu cards, dish presentation photos, and multi-course buffet options directly above your profile description."}],"form":{"title":"Submit Your Catering Business","name_label":"Catering Business Name *","cuisine_label":"Cuisine / Specialties *","price_label":"Pricing Tier","banner_label":"Banner Cover Image","gallery_label":"Direct Menu Cards & Showcase Gallery","about_label":"About Your Catering Business","menu_label":"Direct Menu Text & Visual Builder","days_label":"Day-wise Operating / Booking Hours","locations_label":"Service Locations & Branches","submit_btn":{"label":"Submit Catering Listing","url":"#"},"success_msg":"Thank you! Your catering business has been submitted for review. Our team will approve it shortly."}}');

INSERT INTO site_pages (page_name, content_json) VALUES ('listings', '{"seo":{"title":"Explore Catering Services - Catering Menu","description":"Browse and compare top-rated local catering services. Filter by cuisine, event type (weddings, corporate, parties), host ratings, and curated event food menus.","og_image":"https://www.catering-menu.com/assets/img/catering-menu-logo.png"},"hero":{"title":"Explore Catering Services","subtitle":"Find and book premier caterers, banquet chefs, and custom menus for your event."},"search_placeholder":"Search caterers, cuisines, or locations...","filters":{"cuisine_label":"Cuisines","service_label":"Event & Service","rating_label":"Host Rating","clear_btn":"Reset"},"empty_state":{"icon":"fas fa-search","title":"No Catering Services Found","text":"Try adjusting your search term, clearing selected filters, or exploring all cuisines."},"results_text":"caterers available"}');

INSERT INTO site_pages (page_name, content_json) VALUES ('privacy', '{"seo":{"title":"Privacy Policy - Catering Menu","description":"Read the Privacy Policy for Catering Menu. Learn how we collect, safeguard, and respect your information when browsing caterers and event menus.","og_image":"https://www.catering-menu.com/assets/img/catering-menu-logo.png"},"hero":{"title":"Privacy Policy","subtitle":"How we collect, protect, and handle your data with complete transparency."},"last_updated":"September 2026","sections":[{"title":"1. Introduction & Scope","content":"Catering Menu (\u201cwe,\u201d \u201cus,\u201d or \u201cour\u201d) is committed to protecting your privacy and personal data. This Privacy Policy explains our practices regarding the collection, use, and disclosure of information when you access or use https://www.catering-menu.com, its caterer subdomains, and related web services."},{"title":"2. Information We Collect","content":"We collect information voluntarily provided when you submit contact inquiries, register a catering business, leave reviews, or search our directory. This may include your name, email address, phone number, event preferences, and business details. We also collect standard non-identifying technical analytics (browser type, IP address, device telemetry) to optimize page load speeds."},{"title":"3. How We Use Your Information","content":"We use your data strictly to connect you with relevant catering services, process vendor approvals, display authentic client reviews, deliver customer support, prevent fraud, and continuously enhance our platform usability. We never sell your personal contact information to third-party marketing brokers."},{"title":"4. Cookies and Web Analytics","content":"Catering Menu uses essential cookies and local browser storage to save your navigation preferences, filter states, and enhance security. You can adjust your browser settings to reject cookies, though certain interactive features may experience reduced functionality."},{"title":"5. Data Security & Retention","content":"We employ industry-standard encryption, SSL protocols, and restricted cloud access controls to safeguard your data against unauthorized access, modification, or disclosure. We retain data only for as long as necessary to fulfill directory services and legal compliance."},{"title":"6. Your Legal Rights (GDPR / CCPA)","content":"Depending on your jurisdiction, you have the right to access, rectify, or request the erasure of your personal information stored on Catering Menu. To exercise your rights, please reach out to our dedicated privacy office."}],"contact_box":{"title":"Catering Menu Privacy Team","email":"privacy@catering-menu.com","website":"https://www.catering-menu.com"}}');

INSERT INTO site_pages (page_name, content_json) VALUES ('terms', '{"seo":{"title":"Terms of Service - Catering Menu","description":"Read the Terms of Service for Catering Menu. User agreements, vendor listing terms, and platform guidelines.","og_image":"https://www.catering-menu.com/assets/img/catering-menu-logo.png"},"hero":{"title":"Terms of Service","subtitle":"Platform usage agreements, caterer guidelines, and user responsibilities."},"last_updated":"September 2026","sections":[{"title":"1. Acceptance of Terms","content":"By accessing or using Catering Menu (including all branded caterer subdomains), you agree to be bound by these Terms of Service. If you do not agree with any part of these terms, you must discontinue platform use immediately."},{"title":"2. Directory Services & Booking Disclaimers","content":"Catering Menu operates as a discovery directory and showcase platform connecting event organizers with third-party catering businesses. Catering Menu does not prepare food, employ catering kitchen staff, or guarantee the outcome of individual private event contracts. All contracts, menu agreements, deposits, and service commitments are established directly between the host and the caterer."},{"title":"3. Caterer Listing Responsibilities","content":"Caterers registering on Catering Menu guarantee that all business details, licensing, food hygiene certifications, menu prices, and photo assets submitted are accurate, current, and legally owned or authorized. Misleading or fraudulent listings are subject to immediate termination."},{"title":"4. Customer Reviews & Content Guidelines","content":"Reviews and ratings must represent genuine personal experiences from verified hosts or event guests. Defamatory, abusive, competitor-sponsored, or fraudulent reviews are strictly prohibited and will be removed upon detection."},{"title":"5. Intellectual Property","content":"The Catering Menu name, brand assets, proprietary software, design styling, and code are the exclusive intellectual property of Catering Menu. Content uploaded by vendors remains vendor property, with a granted license for directory display."}],"contact_box":{"title":"Catering Menu Legal & Support","email":"legal@catering-menu.com","website":"https://www.catering-menu.com"}}');

INSERT INTO site_pages (page_name, content_json) VALUES ('disclaimer', '{"seo":{"title":"Allergen & Service Disclaimer - Catering Menu","description":"Food safety, dietary allergen advisories, and platform liability disclaimer for Catering Menu.","og_image":"https://www.catering-menu.com/assets/img/catering-menu-logo.png"},"hero":{"title":"Allergen & Service Disclaimer","subtitle":"Important food safety notices, dietary information, and liability guidelines."},"last_updated":"September 2026","sections":[{"title":"1. Food Safety & Allergen Notice","content":"Food menus, dish descriptions, and dietary labels (e.g., Gluten-Free, Nut-Free, Halal, Kosher, Vegan) displayed on Catering Menu are provided directly by listed caterers. Cross-contamination in commercial kitchens is possible. Event hosts and guests with severe food allergies must communicate directly with their selected caterer prior to ordering."},{"title":"2. Pricing & Availability Disclaimers","content":"Prices, minimum guest headcounts, and seasonal menu offerings are subject to change without prior notice by individual catering businesses. Quotes displayed online serve as baseline guides and should be confirmed directly upon formal inquiry."},{"title":"3. Independent Business Verification","content":"While Catering Menu inspects vendor submissions during initial review, hosts are strongly encouraged to verify local food handling permits, commercial insurance, and health department inspection grades independently."}],"contact_box":{"title":"Food Safety Inquiries","email":"support@catering-menu.com","website":"https://www.catering-menu.com"}}');

