INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"La Maison Dor\u00e9e","slug":"la-maison-doree","cuisine":"French Catering","city":"New York","state":"NY","country":"United States","lat":40.758,"lng":-73.9855,"banner_url":"https:\/\/images.unsplash.com\/photo-1517248135467-4c7edcad34c4?w=1400","about_text":"Nestled in the heart of downtown, La Maison Dor\u00e9e is a beacon of French culinary excellence. With over two decades of catering experience for luxury galas and high-profile receptions, our kitchen has been led by award-winning Chef Antoine Beaumont, who brings classical French techniques together with locally sourced seasonal ingredients.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n         LA MAISON DOR\u00c9E \u2014 CATERING MENU\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n\u2500\u2500 PASSED HORS D''OEUVRES \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nSeared Foie Gras with Brioche\nEscargots Tartlets\nTuna Tartare with Avocado Caviar\n\n\u2500\u2500 PLATED DINNER \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nDuck Confit with Braised Lentils\nFilet Mignon with Black Truffle Reduction\nPan-Seared Chilean Sea Bass\nHerb-Crusted Colorado Rack of Lamb\n\n\u2500\u2500 DESSERT STATIONS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nCr\u00e8me Br\u00fbl\u00e9e Flamb\u00e9 Bar\nMini Chocolate Souffl\u00e9 Bites\nArtisanal French Cheese Display","menu_file_path":"","opening_days":"Mon-Sun: 9:00 AM \u2013 9:00 PM","locations":"742 Evergreen Ave, Downtown | Serves Tri-State Area","reviews":[{"name":"Sarah Mitchell","rating":5,"date":"2025-12-15","text":"Incredible catering service for our daughter''s wedding. The duck confit and dessert bar wowed every single guest."},{"name":"James Rodriguez","rating":5,"date":"2025-11-28","text":"Chef Antoine and his team were prompt, polished, and exceptionally professional at our corporate annual gala."}]}');
INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"Sakura Japanese Kitchen","slug":"sakura-japanese-kitchen","cuisine":"Japanese Catering","city":"New York","state":"NY","country":"United States","lat":40.7282,"lng":-73.7949,"banner_url":"https:\/\/images.unsplash.com\/photo-1579027989536-b7b1f875659b?w=1400","about_text":"Sakura Japanese Kitchen brings live sushi bar catering and authentic Japanese dining to private residences and corporate galas. Our master sushi chefs craft fresh nigiri, specialty rolls, and sizzling teppanyaki live for your guests.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n    SAKURA JAPANESE \u2014 EVENT CATERING\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n\u2500\u2500 LIVE SUSHI BAR DISPLAY \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nBluefin Tuna & Salmon Nigiri\nDragon & Rainbow Specialty Rolls\nYellowtail Jalape\u00f1o Sashimi\n\n\u2500\u2500 HOT BUFFET & TEPPANYAKI \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nWagyu Beef Skewers\nBlack Cod Miso\nCrispy Vegetable Gyoza\n\n\u2500\u2500 SAKE & BEVERAGE STATION \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nJunmai Daiginjo Sake Tasting\nJapanese Highball Cocktails\nMatcha Green Tea Tiramisu","menu_file_path":"","opening_days":"Tue-Sun: 10:00 AM \u2013 10:00 PM","locations":"88 Cherry Blossom Lane, East Side | Serves Metro Area","reviews":[{"name":"Mike Tanaka","rating":5,"date":"2026-01-10","text":"The live sushi counter was the absolute highlight of our company summit. Extremely fresh fish and pristine presentation."}]}');
