INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"Verde Trattoria","slug":"verde-trattoria","cuisine":"Italian Catering","city":"New York","state":"NY","country":"United States","lat":40.7178,"lng":-73.9988,"banner_url":"https:\/\/images.unsplash.com\/photo-1414235077428-338989a2e8c0?w=1400","about_text":"Verde Trattoria provides authentic Italian family-style catering, wood-fired pizza ovens on wheels, and handcrafted pasta bars for private parties, rehearsal dinners, and weddings.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r\n     VERDE TRATTORIA \u2014 ITALIAN CATERING\r\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r\n\r\n\u2500\u2500 ANTIPASTI GRAZING TABLE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nImported Prosciutto di Parma & Burrata\r\nBruschetta al Pomodoro e Basilico\r\nMarinated Artichokes & Olives\r\n\r\n\u2500\u2500 LIVE PASTA WHEEL & WOOD OVEN \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nParmesano Reggiano Fettuccine Wheel\r\nPappardelle al Rag\u00f9 di Cinghiale\r\nNeapolitan Pizza Station","menu_file_path":"","opening_days":"Mon-Sun: 10:00 AM \u2013 9:00 PM","locations":"15 Olive Garden Blvd | Serves All Boroughs","reviews":[{"name":"Rachel Green","rating":5,"date":"2026-01-25","text":"The cheese wheel pasta station was an unforgettable experience at our anniversary party."}]}');
